from pydantic import BaseModel, computed_field

router = APIRouter(prefix="/support/tickets")

class SupportTicketOverview(BaseModel):
    ticket_id: str
    subject: str
    status: str
    _customer_lifetime_spend_cents: int = 0
    _churn_risk_score: float = 0.0

    @computed_field
    @property
    def customer_tier_label(self) -> str:
        if self._customer_lifetime_spend_cents > 5000000:
            return "WHALE_ENTERPRISE_VIP"
        return "STANDARD"

    @computed_field
    @property
    def internal_churn_propensity(self) -> float:
        return self._churn_risk_score

