from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

router = APIRouter(prefix="/support/tickets")

class SupportTicketOverview(BaseModel):
    ticket_id: str
    subject: str
    status: str

@router.get("/{ticket_id}/view", response_model=SupportTicketOverview)
async def view_support_ticket(
    ticket_id: str,
    ticket_svc: TicketService = Depends(get_ticket_service),
    caller: User = Depends(get_authenticated_user)
):
    ticket = await ticket_svc.get_ticket(ticket_id)
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")
    if ticket.author_id != caller.id and not caller.is_support_agent:
        raise HTTPException(status_code=403, detail="Forbidden: user lacks permission to view tickets filed by other accounts")

    return SupportTicketOverview(
        ticket_id=ticket.id,
        subject=ticket.subject,
        status=ticket.status
    )
